/**
 * Bunny SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from Bunny's OpenAPI
 * documents in `specs/`). `storage.ts` is a hand-written Edge Storage client.
 * Everything else in this folder is hand-written support for the generated
 * code.
 *
 * @example
 * ```ts
 * import * as Bunny from "alchemy-bunny-sdk";
 *
 * const zone = yield* Bunny.Core.getStorageZone({ id: 123 });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  BunnyProtocol,
  BunnyDatabaseProtocol,
  type BunnyOpError,
  type BunnyOpContext,
} from "./protocol.ts";
export { paginateHasMore } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Core from "./services/core.ts";
export * as Compute from "./services/compute.ts";
export * as Database from "./services/database.ts";
export * as Storage from "./storage.ts";
export { checksumOf } from "./checksum.ts";
export * as Sql from "./sql.ts";
